def get_nilai_persediaan_data(filters):
    def get_opening_balance(item_code, filters):
        """Get opening balance for an item before the from_date"""
        conditions = [f"item_code = '{item_code}'", "docstatus = 1"]
        
        if filters.get("company"):
            conditions.append(f"company = '{filters.get('company')}'")
        if filters.get("warehouse"):
            conditions.append(f"warehouse = '{filters.get('warehouse')}'")
        if filters.get("from_date"):
            conditions.append(f"posting_date < '{filters.get('from_date')}'")
        
        where_clause = " AND ".join(conditions)
        
        opening_data = frappe.db.sql(f"""
            SELECT 
                SUM(CASE WHEN actual_qty > 0 THEN actual_qty ELSE 0 END) as qty_in,
                SUM(CASE WHEN actual_qty > 0 THEN actual_qty * incoming_rate ELSE 0 END) as amount_in,
                SUM(CASE WHEN actual_qty < 0 THEN ABS(actual_qty) ELSE 0 END) as qty_out,
                SUM(CASE WHEN actual_qty < 0 THEN ABS(stock_value_difference) ELSE 0 END) as amount_out
            FROM `tabStock Ledger Entry`
            WHERE {where_clause}
        """, as_dict=True)
        
        if opening_data and opening_data[0]:
            data = opening_data[0]
            opening_qty = frappe.utils.flt(data.qty_in) - frappe.utils.flt(data.qty_out)
            opening_amount = frappe.utils.flt(data.amount_in) - frappe.utils.flt(data.amount_out)
            return {'qty': opening_qty, 'amount': opening_amount}
        
        return {'qty': 0, 'amount': 0}
    
    def get_kartu_stok_data(filters):
        """Reuse the kartu stok logic with simplified structure"""
        def parse_stock_queue(stock_queue_str):
            """Parse stock queue string and return list of [qty, rate] pairs"""
            if not stock_queue_str or stock_queue_str == "[]":
                return []
            
            try:
                queue_data = json.loads(stock_queue_str)
                batches = []
                if isinstance(queue_data[0], list):
                    for i in range(0, len(queue_data)):
                        qty = frappe.utils.flt(queue_data[i][0])
                        rate = frappe.utils.flt(queue_data[i][1])
                        batches.append([qty, rate])
                else:
                    batches.append(queue_data)
                return batches
            except:
                return []
        
        if not filters:
            filters = {}
        
        # Build conditions for filtering
        conditions = []
        if filters.get("company"):
            conditions.append(f"company = '{filters.get('company')}'")
        if filters.get("warehouse"):
            conditions.append(f"warehouse = '{filters.get('warehouse')}'")
        if filters.get("item_code"):
            conditions.append(f"item_code = '{filters.get('item_code')}'")
        if filters.get("from_date"):
            conditions.append(f"posting_date >= '{filters.get('from_date')}'")
        if filters.get("to_date"):
            conditions.append(f"posting_date <= '{filters.get('to_date')}'")
        
        where_clause = " AND " + " AND ".join(conditions) if conditions else ""
        
        # Get all stock ledger entries
        stock_entries = frappe.db.sql(f"""
            SELECT 
                posting_datetime, posting_date, item_code, warehouse, voucher_type, voucher_no,
                actual_qty, incoming_rate, stock_value_difference, stock_queue, name,
                qty_after_transaction, company
            FROM `tabStock Ledger Entry`
            WHERE docstatus = 1 {where_clause}
            ORDER BY item_code, warehouse, posting_datetime, creation
        """, as_dict=True)
        
        result_data = []
        
        for entry in stock_entries:
            if entry.actual_qty > 0:
                # Incoming stock
                result_data.append({
                    'item_code': entry.item_code,
                    'qty_in': entry.actual_qty,
                    'amount_in': entry.actual_qty * entry.incoming_rate,
                    'qty_out': None,
                    'amount_out': None,
                })
            else:
                # Outgoing stock - use FIFO logic for accurate costing
                qty_to_consume = abs(frappe.utils.flt(entry.actual_qty))
                
                # Get the previous stock queue state
                prev_entry = frappe.db.sql(f"""
                    SELECT stock_queue
                    FROM `tabStock Ledger Entry`
                    WHERE item_code = '{entry.item_code}' AND warehouse = '{entry.warehouse}' 
                    AND posting_datetime <= '{entry.posting_datetime}' AND name != '{entry.name}'
                    AND docstatus = 1
                    ORDER BY posting_datetime DESC, creation DESC
                    LIMIT 1
                """, as_dict=True)
                
                queue_before_str = (prev_entry[0].stock_queue if prev_entry[0].stock_queue else "[]") if prev_entry else "[]"
                queue_before = parse_stock_queue(queue_before_str)
                
                # Calculate consumption from batches
                remaining_qty = qty_to_consume
                temp_queue = queue_before.copy()
                total_consumed_amount = 0
                
                while remaining_qty > 0 and temp_queue:
                    batch = temp_queue[0]
                    batch_qty = batch[0]
                    batch_rate = batch[1]
                    
                    if batch_qty <= remaining_qty:
                        # Consume entire batch
                        total_consumed_amount += batch_qty * batch_rate
                        remaining_qty -= batch_qty
                        temp_queue.pop(0)
                    else:
                        # Partially consume batch
                        total_consumed_amount += remaining_qty * batch_rate
                        temp_queue[0] = [batch_qty - remaining_qty, batch_rate]
                        remaining_qty = 0
                
                result_data.append({
                    'item_code': entry.item_code,
                    'qty_in': None,
                    'amount_in': None,
                    'qty_out': qty_to_consume,
                    'amount_out': total_consumed_amount,
                })
                
        return result_data
    
    def get_report_summary(data):
        if not data:
            return []
        
        total_balance_qty = sum(frappe.utils.flt(row.get('balance_qty', 0)) for row in data)
        total_balance_amount = sum(frappe.utils.flt(row.get('balance_amount', 0)) for row in data)
        total_qty_in = sum(frappe.utils.flt(row.get('qty_in', 0)) for row in data)
        total_amount_in = sum(frappe.utils.flt(row.get('amount_in', 0)) for row in data)
        total_qty_out = sum(frappe.utils.flt(row.get('qty_out', 0)) for row in data)
        total_amount_out = sum(frappe.utils.flt(row.get('amount_out', 0)) for row in data)
        
        return [
            {
                "value": total_qty_in,
                "label": "Total Qty In",
                "datatype": "Float",
            },
            {
                "value": total_amount_in,
                "label": "Total Amount In",
                "datatype": "Currency",
            },
            {
                "value": total_qty_out,
                "label": "Total Qty Out",
                "datatype": "Float",
            },
            {
                "value": total_amount_out,
                "label": "Total Amount Out",
                "datatype": "Currency",
            },
            {
                "value": total_balance_qty,
                "label": "Total Balance Qty",
                "datatype": "Float",
            },
            {
                "value": total_balance_amount,
                "label": "Total Balance Amount",
                "datatype": "Currency",
            }
        ]
    
    
    if not filters:
        filters = {}
    
    # Get the detailed kartu stok data
    kartu_stok_data = get_kartu_stok_data(filters)
    
    # Group by item_code
    item_summary = {}
    
    for row in kartu_stok_data:
        item_code = row.get('item_code')
        if not item_code:
            continue
            
        if item_code not in item_summary:
            # Get item details
            item_details = frappe.db.get_value("Item", item_code, 
                ["item_name", "item_group"], as_dict=True)
            
            item_summary[item_code] = {
                'item_code': item_code,
                'item_name': item_details.item_name if item_details else '',
                'item_group': item_details.item_group if item_details else '',
                'qty_start': 0,
                'amount_start': 0,
                'qty_in': 0,
                'amount_in': 0,
                'qty_out': 0,
                'amount_out': 0,
                'balance_qty': 0,
                'balance_amount': 0
            }
        
        # Accumulate quantities and amounts
        if row.get('qty_in'):
            item_summary[item_code]['qty_in'] += frappe.utils.flt(row.get('qty_in', 0))
            item_summary[item_code]['amount_in'] += frappe.utils.flt(row.get('amount_in', 0))
            
        if row.get('qty_out'):
            item_summary[item_code]['qty_out'] += frappe.utils.flt(row.get('qty_out', 0))
            item_summary[item_code]['amount_out'] += frappe.utils.flt(row.get('amount_out', 0))
    
    # Calculate opening balances and final balances
    for item_code, summary in item_summary.items():
        # Get opening balance (before from_date if specified)
        if filters.get('from_date'):
            opening_balance = get_opening_balance(item_code, filters)
            summary['qty_start'] = opening_balance['qty']
            summary['amount_start'] = opening_balance['amount']
        
        # Calculate final balance
        summary['balance_qty'] = (summary['qty_start'] + summary['qty_in'] - summary['qty_out'])
        summary['balance_amount'] = (summary['amount_start'] + summary['amount_in'] - summary['amount_out'])
    
    # Convert to list and sort by item_group
    result = list(item_summary.values())
    result = sorted(result, key=lambda x: (x.get('item_group', ''), x.get('item_code', '')))
    
    return result
    
